    // --version answer) route first, exactly as before.
    final repoFree = _repoFreeCommands(hostCwd, env)[subcommand];
    if (repoFree != null) return repoFree(prologue.rest.sublist(1));

    final root = _findGitRoot(hostCwd);
    if (root == null) {
