    return Ok(const StageResult(stdout: [], stderr: [], exitCode: 0));
  }
  final plan = parseXargsArgs(stage.args);
  if (plan.commandIndex >= stage.args.length) {
    return Ok(
      StageResult(
        stdout: const [],
        stderr: utf8.encode('xargs: missing command\n'),
        exitCode: 1,
