  final initialArgs = stage.args.sublist(plan.commandIndex + 1);
  final invocations = xargsInvocations(
    initialArgs,
    await file.readAsLines(),
    plan.placeholder,
  );
  final stdout = <int>[];
  final stderr = <int>[];
